SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF NOT EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE Version=3)
BEGIN
CREATE TABLE dbo.DomainVerifications(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, Method varchar(20) NOT NULL CHECK(Method IN('DnsTxt','File','SearchConsole')), ChallengeHash varchar(64) NOT NULL, VerifiedUtc datetime2 NULL, ExpiresUtc datetime2 NOT NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_DomainVerifications_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_DomainVerifications_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_DomainVerifications_Tenant_Created ON dbo.DomainVerifications(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.WebsiteSettings(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, SettingsJson nvarchar(max) NOT NULL CHECK(ISJSON(SettingsJson)=1), Environment varchar(20) NOT NULL CHECK(Environment IN('Staging','Production')), PublishingAuthorized bit NOT NULL DEFAULT 0, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_WebsiteSettings_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_WebsiteSettings_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_WebsiteSettings_Tenant_Created ON dbo.WebsiteSettings(TenantId,CreatedUtc DESC);
CREATE UNIQUE INDEX UX_WebsiteSettings_Website ON dbo.WebsiteSettings(TenantId,WebsiteId);
CREATE TABLE dbo.PublishingConnections(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, Provider varchar(40) NOT NULL, Endpoint nvarchar(2048) NOT NULL, EncryptedCredentials varbinary(max) NULL, IsEnabled bit NOT NULL DEFAULT 0, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_PublishingConnections_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_PublishingConnections_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_PublishingConnections_Tenant_Created ON dbo.PublishingConnections(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.CrawlRuns(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, Status varchar(20) NOT NULL CHECK(Status IN('Queued','Running','Completed','Failed','Cancelled')), StartedUtc datetime2 NULL, FinishedUtc datetime2 NULL, MaxPages int NOT NULL CHECK(MaxPages BETWEEN 1 AND 100000), PagesProcessed int NOT NULL DEFAULT 0, Error nvarchar(2000) NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_CrawlRuns_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_CrawlRuns_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_CrawlRuns_Tenant_Created ON dbo.CrawlRuns(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.CrawledPages(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, CrawlRunId uniqueidentifier NOT NULL, Url nvarchar(2048) NOT NULL, UrlHash binary(32) NOT NULL, FinalUrl nvarchar(2048) NULL, HttpStatus int NULL CHECK(HttpStatus BETWEEN 100 AND 599), Title nvarchar(1000) NULL, MetaDescription nvarchar(2000) NULL, CanonicalUrl nvarchar(2048) NULL, ContentHash binary(32) NULL, DurationMs int NULL CHECK(DurationMs>=0), CrawledUtc datetime2 NOT NULL, FOREIGN KEY(TenantId,CrawlRunId) REFERENCES dbo.CrawlRuns(TenantId,Id), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_CrawledPages_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_CrawledPages_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_CrawledPages_Tenant_Created ON dbo.CrawledPages(TenantId,CreatedUtc DESC);
CREATE UNIQUE INDEX UX_CrawledPages_Run_Url ON dbo.CrawledPages(TenantId,CrawlRunId,UrlHash);
CREATE TABLE dbo.PageLinks(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, PageId uniqueidentifier NOT NULL, TargetUrl nvarchar(2048) NOT NULL, IsInternal bit NOT NULL, IsNoFollow bit NOT NULL, FOREIGN KEY(TenantId,PageId) REFERENCES dbo.CrawledPages(TenantId,Id), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_PageLinks_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_PageLinks_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_PageLinks_Tenant_Created ON dbo.PageLinks(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.SeoRules(Code varchar(100) PRIMARY KEY, Name nvarchar(200) NOT NULL, Severity varchar(20) NOT NULL CHECK(Severity IN('Critical','Warning','Info')), Weight int NOT NULL CHECK(Weight>=0), IsEnabled bit NOT NULL DEFAULT 1);
CREATE TABLE dbo.SeoFindings(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, PageId uniqueidentifier NOT NULL, RuleCode varchar(100) NOT NULL REFERENCES dbo.SeoRules(Code), Evidence nvarchar(max) NOT NULL, Status varchar(20) NOT NULL CHECK(Status IN('Open','Resolved','Ignored')), FOREIGN KEY(TenantId,PageId) REFERENCES dbo.CrawledPages(TenantId,Id), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_SeoFindings_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_SeoFindings_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_SeoFindings_Tenant_Created ON dbo.SeoFindings(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.FindingHistory(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, FindingId uniqueidentifier NOT NULL, Status varchar(20) NOT NULL, FOREIGN KEY(TenantId,FindingId) REFERENCES dbo.SeoFindings(TenantId,Id), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_FindingHistory_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_FindingHistory_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_FindingHistory_Tenant_Created ON dbo.FindingHistory(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.Sitemaps(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, Url nvarchar(2048) NOT NULL, FetchedUtc datetime2 NULL, HttpStatus int NULL, ContentHash binary(32) NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_Sitemaps_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_Sitemaps_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_Sitemaps_Tenant_Created ON dbo.Sitemaps(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.RobotsSnapshots(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, Content nvarchar(max) NOT NULL, HttpStatus int NOT NULL, FetchedUtc datetime2 NOT NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_RobotsSnapshots_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_RobotsSnapshots_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_RobotsSnapshots_Tenant_Created ON dbo.RobotsSnapshots(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.PageSpeedRuns(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, Url nvarchar(2048) NOT NULL, Device varchar(10) NOT NULL CHECK(Device IN('Mobile','Desktop')), LabMetricsJson nvarchar(max) NULL CHECK(ISJSON(LabMetricsJson)=1), FieldMetricsJson nvarchar(max) NULL CHECK(ISJSON(FieldMetricsJson)=1), ProviderError nvarchar(2000) NULL, TestedUtc datetime2 NOT NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_PageSpeedRuns_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_PageSpeedRuns_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_PageSpeedRuns_Tenant_Created ON dbo.PageSpeedRuns(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.ProviderConnections(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, Provider varchar(40) NOT NULL, EncryptedTokens varbinary(max) NULL, Scopes nvarchar(2000) NULL, ExpiresUtc datetime2 NULL, DisconnectedUtc datetime2 NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_ProviderConnections_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_ProviderConnections_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_ProviderConnections_Tenant_Created ON dbo.ProviderConnections(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.ProviderSyncRuns(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, ConnectionId uniqueidentifier NOT NULL, Status varchar(20) NOT NULL, FinishedUtc datetime2 NULL, Error nvarchar(2000) NULL, FOREIGN KEY(TenantId,ConnectionId) REFERENCES dbo.ProviderConnections(TenantId,Id), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_ProviderSyncRuns_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_ProviderSyncRuns_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_ProviderSyncRuns_Tenant_Created ON dbo.ProviderSyncRuns(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.SearchConsoleMetrics(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, MetricDate date NOT NULL, Query nvarchar(1000) NOT NULL, PageUrl nvarchar(2048) NOT NULL, Country varchar(3) NOT NULL, Device varchar(20) NOT NULL, Clicks bigint NOT NULL CHECK(Clicks>=0), Impressions bigint NOT NULL CHECK(Impressions>=0), Ctr decimal(12,8) NOT NULL, AveragePosition decimal(12,4) NOT NULL, SyncedUtc datetime2 NOT NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_SearchConsoleMetrics_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_SearchConsoleMetrics_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_SearchConsoleMetrics_Tenant_Created ON dbo.SearchConsoleMetrics(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.AnalyticsMetrics(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, MetricDate date NOT NULL, PagePath nvarchar(2048) NOT NULL, Sessions bigint NOT NULL CHECK(Sessions>=0), Conversions decimal(18,4) NOT NULL CHECK(Conversions>=0), SyncedUtc datetime2 NOT NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_AnalyticsMetrics_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_AnalyticsMetrics_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_AnalyticsMetrics_Tenant_Created ON dbo.AnalyticsMetrics(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.KeywordGroups(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, Name nvarchar(200) NOT NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_KeywordGroups_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_KeywordGroups_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_KeywordGroups_Tenant_Created ON dbo.KeywordGroups(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.Keywords(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, GroupId uniqueidentifier NULL, Phrase nvarchar(450) NOT NULL, TargetUrl nvarchar(2048) NULL, Intent varchar(30) NULL, Locale varchar(20) NOT NULL, FOREIGN KEY(TenantId,GroupId) REFERENCES dbo.KeywordGroups(TenantId,Id), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_Keywords_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_Keywords_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_Keywords_Tenant_Created ON dbo.Keywords(TenantId,CreatedUtc DESC);
CREATE UNIQUE INDEX UX_Keywords_Phrase ON dbo.Keywords(TenantId,WebsiteId,Phrase,Locale);
CREATE TABLE dbo.KeywordSuggestions(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, Phrase nvarchar(450) NOT NULL, Source varchar(40) NOT NULL, IsAiSuggestion bit NOT NULL, SearchVolume bigint NULL CHECK(SearchVolume>=0), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_KeywordSuggestions_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_KeywordSuggestions_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_KeywordSuggestions_Tenant_Created ON dbo.KeywordSuggestions(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.KeywordRankSnapshots(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, KeywordId uniqueidentifier NOT NULL, Provider varchar(40) NOT NULL, Position int NULL CHECK(Position>0), Device varchar(20) NOT NULL, Location nvarchar(200) NOT NULL, CheckedUtc datetime2 NOT NULL, Cost decimal(18,6) NULL CHECK(Cost>=0), Error nvarchar(2000) NULL, FOREIGN KEY(TenantId,KeywordId) REFERENCES dbo.Keywords(TenantId,Id), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_KeywordRankSnapshots_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_KeywordRankSnapshots_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_KeywordRankSnapshots_Tenant_Created ON dbo.KeywordRankSnapshots(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.Competitors(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, Domain nvarchar(253) NOT NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_Competitors_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_Competitors_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_Competitors_Tenant_Created ON dbo.Competitors(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.BacklinkSnapshots(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, Provider varchar(40) NOT NULL, SourceUrl nvarchar(2048) NOT NULL, TargetUrl nvarchar(2048) NOT NULL, ObservedUtc datetime2 NOT NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_BacklinkSnapshots_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_BacklinkSnapshots_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_BacklinkSnapshots_Tenant_Created ON dbo.BacklinkSnapshots(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.AiPrompts(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), Name nvarchar(200) NOT NULL, Version int NOT NULL CHECK(Version>0), Template nvarchar(max) NOT NULL, Locale varchar(20) NOT NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_AiPrompts_TenantId_Id UNIQUE(TenantId,Id));
CREATE INDEX IX_AiPrompts_Tenant_Created ON dbo.AiPrompts(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.AiJobs(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, PromptId uniqueidentifier NULL, Status varchar(20) NOT NULL, Model nvarchar(100) NULL, Error nvarchar(2000) NULL, FinishedUtc datetime2 NULL, FOREIGN KEY(TenantId,PromptId) REFERENCES dbo.AiPrompts(TenantId,Id), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_AiJobs_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_AiJobs_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_AiJobs_Tenant_Created ON dbo.AiJobs(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.AiUsage(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), AiJobId uniqueidentifier NOT NULL, InputTokens int NOT NULL CHECK(InputTokens>=0), OutputTokens int NOT NULL CHECK(OutputTokens>=0), Cost decimal(18,6) NOT NULL CHECK(Cost>=0), FOREIGN KEY(TenantId,AiJobId) REFERENCES dbo.AiJobs(TenantId,Id), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_AiUsage_TenantId_Id UNIQUE(TenantId,Id));
CREATE INDEX IX_AiUsage_Tenant_Created ON dbo.AiUsage(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.ContentDrafts(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, PageUrl nvarchar(2048) NOT NULL, Status varchar(20) NOT NULL CHECK(Status IN('Draft','Review','Approved','Published','RolledBack')), Locale varchar(20) NOT NULL, AuthorId uniqueidentifier NOT NULL REFERENCES dbo.Users(Id), IsDeleted bit NOT NULL DEFAULT 0, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_ContentDrafts_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_ContentDrafts_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_ContentDrafts_Tenant_Created ON dbo.ContentDrafts(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.DraftVersions(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), DraftId uniqueidentifier NOT NULL, Version int NOT NULL CHECK(Version>0), BeforeJson nvarchar(max) NOT NULL CHECK(ISJSON(BeforeJson)=1), AfterJson nvarchar(max) NOT NULL CHECK(ISJSON(AfterJson)=1), EvidenceJson nvarchar(max) NOT NULL CHECK(ISJSON(EvidenceJson)=1), FOREIGN KEY(TenantId,DraftId) REFERENCES dbo.ContentDrafts(TenantId,Id), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_DraftVersions_TenantId_Id UNIQUE(TenantId,Id));
CREATE INDEX IX_DraftVersions_Tenant_Created ON dbo.DraftVersions(TenantId,CreatedUtc DESC);
CREATE UNIQUE INDEX UX_DraftVersions_Number ON dbo.DraftVersions(TenantId,DraftId,Version);
CREATE TABLE dbo.DraftApprovals(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), DraftVersionId uniqueidentifier NOT NULL, ApproverId uniqueidentifier NOT NULL REFERENCES dbo.Users(Id), Decision varchar(20) NOT NULL CHECK(Decision IN('Approved','Rejected')), FOREIGN KEY(TenantId,DraftVersionId) REFERENCES dbo.DraftVersions(TenantId,Id), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_DraftApprovals_TenantId_Id UNIQUE(TenantId,Id));
CREATE INDEX IX_DraftApprovals_Tenant_Created ON dbo.DraftApprovals(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.PublishJobs(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NOT NULL, DraftVersionId uniqueidentifier NOT NULL, ApprovalId uniqueidentifier NOT NULL, Status varchar(20) NOT NULL, IdempotencyKey uniqueidentifier NOT NULL UNIQUE, IsDryRun bit NOT NULL DEFAULT 1, Error nvarchar(2000) NULL, FOREIGN KEY(TenantId,DraftVersionId) REFERENCES dbo.DraftVersions(TenantId,Id), FOREIGN KEY(TenantId,ApprovalId) REFERENCES dbo.DraftApprovals(TenantId,Id), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_PublishJobs_TenantId_Id UNIQUE(TenantId,Id), CONSTRAINT FK_PublishJobs_Websites FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id));
CREATE INDEX IX_PublishJobs_Tenant_Created ON dbo.PublishJobs(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.PublishBackups(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), PublishJobId uniqueidentifier NOT NULL, OriginalJson nvarchar(max) NOT NULL CHECK(ISJSON(OriginalJson)=1), OriginalContentHash binary(32) NOT NULL, FOREIGN KEY(TenantId,PublishJobId) REFERENCES dbo.PublishJobs(TenantId,Id), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_PublishBackups_TenantId_Id UNIQUE(TenantId,Id));
CREATE INDEX IX_PublishBackups_Tenant_Created ON dbo.PublishBackups(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.ScheduledJobs(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), WebsiteId uniqueidentifier NULL, Kind varchar(40) NOT NULL, CronExpression varchar(100) NOT NULL, IsEnabled bit NOT NULL DEFAULT 0, IsDryRun bit NOT NULL DEFAULT 1, NextRunUtc datetime2 NULL, FOREIGN KEY(TenantId,WebsiteId) REFERENCES dbo.Websites(TenantId,Id), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_ScheduledJobs_TenantId_Id UNIQUE(TenantId,Id));
CREATE INDEX IX_ScheduledJobs_Tenant_Created ON dbo.ScheduledJobs(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.Notifications(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), UserId uniqueidentifier NOT NULL REFERENCES dbo.Users(Id), Kind varchar(40) NOT NULL, Message nvarchar(2000) NOT NULL, ReadUtc datetime2 NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_Notifications_TenantId_Id UNIQUE(TenantId,Id));
CREATE INDEX IX_Notifications_Tenant_Created ON dbo.Notifications(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.ReportDefinitions(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), Name nvarchar(200) NOT NULL, SettingsJson nvarchar(max) NOT NULL CHECK(ISJSON(SettingsJson)=1), EmailOptIn bit NOT NULL DEFAULT 0, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_ReportDefinitions_TenantId_Id UNIQUE(TenantId,Id));
CREATE INDEX IX_ReportDefinitions_Tenant_Created ON dbo.ReportDefinitions(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.ReportRuns(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), DefinitionId uniqueidentifier NOT NULL, Status varchar(20) NOT NULL, StorageKey nvarchar(450) NULL, FinishedUtc datetime2 NULL, FOREIGN KEY(TenantId,DefinitionId) REFERENCES dbo.ReportDefinitions(TenantId,Id), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_ReportRuns_TenantId_Id UNIQUE(TenantId,Id));
CREATE INDEX IX_ReportRuns_Tenant_Created ON dbo.ReportRuns(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.Plans(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), Name nvarchar(100) NOT NULL UNIQUE, SiteLimit int NOT NULL CHECK(SiteLimit>0), UserLimit int NOT NULL CHECK(UserLimit>0), PagesPerCrawl int NOT NULL CHECK(PagesPerCrawl>0), AiCredits int NOT NULL CHECK(AiCredits>=0), FeatureFlagsJson nvarchar(max) NOT NULL CHECK(ISJSON(FeatureFlagsJson)=1), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL);
CREATE TABLE dbo.Subscriptions(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), PlanId uniqueidentifier NOT NULL REFERENCES dbo.Plans(Id), Status varchar(20) NOT NULL CHECK(Status IN('Trial','Active','PastDue','Cancelled')), EndsUtc datetime2 NULL, BillingReference nvarchar(200) NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_Subscriptions_TenantId_Id UNIQUE(TenantId,Id));
CREATE INDEX IX_Subscriptions_Tenant_Created ON dbo.Subscriptions(TenantId,CreatedUtc DESC);
CREATE TABLE dbo.UsageMeters(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), TenantId uniqueidentifier NOT NULL REFERENCES dbo.Tenants(Id), Metric varchar(50) NOT NULL, PeriodStart date NOT NULL, Quantity bigint NOT NULL CHECK(Quantity>=0), CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_UsageMeters_TenantId_Id UNIQUE(TenantId,Id));
CREATE INDEX IX_UsageMeters_Tenant_Created ON dbo.UsageMeters(TenantId,CreatedUtc DESC);
